314:   // ---------------- combat ----------------
315:   raySphere(origin, dir, center, radius) {
316:     const ox = center.x - origin.x, oy = center.y - origin.y, oz = center.z - origin.z;
317:     const t = ox * dir.x + oy * dir.y + oz * dir.z;
318:     if (t < 0) return null;
319:     const d2 = ox * ox + oy * oy + oz * oz - t * t;
320:     const r2 = radius * radius;
321:     if (d2 > r2) return null;
322:     return t - Math.sqrt(r2 - d2);
323:   }
