329:   firePlayerWeapon(player, w) {
330:     player.lastWeaponId = w.id;
331:     this.audio[w.id === 'scatter' ? 'shotgun' : w.id === 'rocket' ? 'rocket' : w.id === 'rail' ? 'rail' : 'spin']();
332:     this.viewModel.fire();
333:     this.recoil = Math.min(1.2, this.recoil + (w.kick || 1));
334:     if (!w.infinite) player.ammo[w.id] = Math.max(0, player.ammo[w.id] - 1);
335: 
336:     const origin = player.eyePosition;
337:     const forward = player.forward;
338:     const muzzle = origin.clone().addScaledVector(forward, 0.75).addScaledVector(player.flatRight, 0.26).add(new THREE.Vector3(0, -0.14, 0));
339:     const quadMult = player.quad > 0 ? 4 : 1;
340: 
341:     if (w.id === 'scatter') {
342:       let anyHit = false;
343:       for (let i = 0; i < w.pellets; i++) {
344:         const spread = w.spread;
345:         const rx = (Math.random() - 0.5) * 2 * spread;
346:         const ry = (Math.random() - 0.5) * 2 * spread;
347:         const dir = forward.clone().addScaledVector(player.flatRight, rx).addScaledVector(UP, ry).normalize();
348:         const res = this.hitscan(origin, dir, w.range, w.damage * quadMult, player, w.id, false);
349:         if (i % 3 === 0) {
350:           this.effects.beam(muzzle, res.point, 0xffcf8a, 0.018, 0.055);
351:         }
352:         if (res.target) anyHit = true;
353:       }
354:       if (anyHit) this.hud.hitmarker(false);
355:     } else if (w.id === 'rail') {
356:       const res = this.hitscan(origin, forward, w.range, w.damage * quadMult, player, w.id, true);
357:       const end = res.point.clone().addScaledVector(forward, -0.15);
358:       this.effects.rail(muzzle, end);
359:       if (res.target) {
360:         this.hud.hitmarker(false);
361:         this.effects.burst(res.point, 14, { color: 0x9dfbff, speed: 5, size: 0.18, life: 0.35, grav: 3 });
362:       }
363:       this.shake = Math.max(this.shake, 0.4);
364:     } else {
365:       this.spawnProjectile(player, w, origin, forward, muzzle, quadMult);
366:     }
367:     // tiny camera kick
368:     this.cameraKick = (this.cameraKick || 0) + 0.02 * (w.kick || 1);
369:   }
