371:   hitscan(origin, dir, range, damage, owner, weaponId, strong) {
372:     const wall = this.world.raycast(origin, dir, range);
373:     let wallDist = wall ? wall.distance : range;
374:     let point = wall ? wall.point.clone() : origin.clone().addScaledVector(dir, range);
375:     let closest = null, closestDist = wallDist;
376:     for (const e of this.combatants) {
377:       if (e === owner || !e.alive) continue;
378:       const center = this.entityCenter(e);
379:       const t = this.raySphere(origin, dir, center, e.isPlayer ? 0.62 : 0.82);
380:       if (t !== null && t < closestDist) {
381:         closestDist = t;
382:         closest = e;
383:         point = origin.clone().addScaledVector(dir, t);
384:       }
385:     }
386:     if (closest) {
387:       closest.hurt(damage, owner, this, weaponId);
388:       this.effects.spark(point, dir.clone().negate(), weaponId === 'rail' ? 0x99fbff : 0xffc080, strong ? 16 : 6);
389:       this.audio.hit();
390:     } else if (wall) {
391:       const n = wall.face ? wall.face.normal.clone().transformDirection(wall.object.matrixWorld) : dir.clone().negate();
392:       this.effects.spark(point, n, 0xffc080, 5);
393:     }
394:     return { point, target: closest };
395:   }
