397:   spawnProjectile(owner, w, origin, forward, muzzle, quadMult) {
398:     const isRocket = w.id === 'rocket';
399:     const g = new THREE.Group();
400:     if (isRocket) {
401:       const body = new THREE.Mesh(new THREE.CylinderGeometry(0.11, 0.15, 0.6, 10), this.projectileMats.rocket);
402:       body.rotation.x = Math.PI / 2;
403:       const tip = new THREE.Mesh(new THREE.ConeGeometry(0.16, 0.28, 10), new THREE.MeshBasicMaterial({ color: 0xfff0c0 }));
404:       tip.rotation.x = -Math.PI / 2;
405:       tip.position.z = -0.42;
406:       const ring = new THREE.Mesh(new THREE.TorusGeometry(0.16, 0.025, 4, 14), new THREE.MeshBasicMaterial({ color: 0xff6a00 }));
407:       ring.position.z = 0.1;
408:       g.add(body, tip, ring);
409:     } else {
410:       const disc = new THREE.Mesh(new THREE.CylinderGeometry(0.26, 0.26, 0.055, 20), this.projectileMats.spin);
411:       disc.rotation.x = Math.PI / 2;
412:       const rim = new THREE.Mesh(new THREE.TorusGeometry(0.27, 0.03, 4, 22), new THREE.MeshBasicMaterial({ color: 0xbefaff }));
413:       g.add(disc, rim);
414:     }
415:     const glow = new THREE.Sprite(new THREE.SpriteMaterial({
416:       map: isRocket ? this.projectileMats.rocketGlow : this.projectileMats.spinGlow,
417:       color: isRocket ? 0xffb060 : 0x66ddff,
418:       transparent: true, opacity: 0.9, blending: THREE.AdditiveBlending, depthWrite: false
419:     }));
420:     glow.scale.setScalar(isRocket ? 2.6 : 1.8);
421:     g.add(glow);
422:     const start = origin.clone().addScaledVector(forward, 0.85);
423:     if (this.world.collideSphere(start, 0.2)) start.copy(origin).addScaledVector(forward, 0.35);
424:     g.position.copy(start);
425:     this.scene.add(g);
426:     const proj = {
427:       owner, weapon: w, pos: start.clone(), prev: start.clone(),
428:       vel: forward.clone().multiplyScalar(w.speed),
429:       gravity: isRocket ? 1.1 : 2.0,
430:       damage: w.damage * quadMult, splash: w.splash * quadMult, radius: w.splashRadius,
431:       life: 6, mesh: g, type: isRocket ? 'rocket' : 'spin',
432:       trailTimer: 0, directHit: null,
433:     };
434:     this.projectiles.push(proj);
435:   }
