437:   botFire(bot, dir, dist) {
438:     const origin = bot.eyePosition;
439:     const start = origin.clone().addScaledVector(dir, 0.9);
440:     const g = new THREE.Group();
441:     const orb = new THREE.Mesh(new THREE.SphereGeometry(0.16, 10, 8), new THREE.MeshBasicMaterial({ color: bot.color }));
442:     const ring = new THREE.Mesh(new THREE.TorusGeometry(0.24, 0.03, 4, 14), new THREE.MeshBasicMaterial({ color: bot.color, transparent: true, opacity: 0.8 }));
443:     g.add(orb, ring);
444:     const glow = new THREE.Sprite(new THREE.SpriteMaterial({
445:       map: this.projectileMats.spinGlow, color: bot.color, transparent: true, opacity: 0.8, blending: THREE.AdditiveBlending, depthWrite: false
446:     }));
447:     glow.scale.setScalar(1.7);
448:     g.add(glow);
449:     g.position.copy(start);
450:     this.scene.add(g);
451:     const proj = {
452:       owner: bot, weapon: null, pos: start.clone(), prev: start.clone(),
453:       vel: dir.clone().multiplyScalar(40),
454:       gravity: 3.4,
455:       damage: 22, splash: 20, radius: 3.1,
456:       life: 5, mesh: g, type: 'bot', color: bot.color,
457:       trailTimer: 0, directHit: null,
458:     };
459:     this.projectiles.push(proj);
460:     this.audio.tone({ f: 760, to: 300, dur: 0.18, type: 'triangle', vol: 0.035, filter: { f: 2200, to: 600, q: 2 } });
461:   }
