463:   updateProjectiles(dt) {
464:     for (let i = this.projectiles.length - 1; i >= 0; i--) {
465:       const p = this.projectiles[i];
466:       p.life -= dt;
467:       if (p.life <= 0) { this.removeProjectile(p); this.projectiles.splice(i, 1); continue; }
468:       p.prev.copy(p.pos);
469:       p.vel.y -= p.gravity * dt;
470:       const speed = p.vel.length();
471:       const steps = Math.max(1, Math.ceil(speed * dt / 0.45));
472:       let exploded = false;
473:       for (let s = 0; s < steps; s++) {
474:         p.pos.addScaledVector(p.vel, dt / steps);
475:         // world
476:         if (this.world.collideSphere(p.pos, 0.18)) {
477:           this.explodeProjectile(p, p.pos.clone());
478:           exploded = true;
479:           break;
480:         }
481:         // entities
482:         for (const e of this.combatants) {
483:           if (!e.alive || e === p.owner) continue;
484:           const c = this.entityCenter(e);
485:           const r = e.isPlayer ? 0.75 : 0.95;
486:           if (p.pos.distanceToSquared(c) < r * r) {
487:             p.directHit = e;
488:             this.explodeProjectile(p, p.pos.clone());
489:             exploded = true;
490:             break;
