229:   box(x, y, z, w, h, d, mat, { solid = true, cast = true, receive = true, ray = true } = {}) {
230:     const mesh = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), mat);
231:     mesh.position.set(x, y, z);
232:     mesh.castShadow = cast;
233:     mesh.receiveShadow = receive;
234:     this.scene.add(mesh);
235:     if (solid) {
236:       this.colliders.push(new THREE.Box3(V(x - w / 2, y - h / 2, z - d / 2), V(x + w / 2, y + h / 2, z + d / 2)));
237:     }
238:     if (ray) this.meshes.push(mesh);
239:     return mesh;
240:   }
