250:   cyl(x, y, z, r, h, mat, { solid = false, seg = 32, cast = true } = {}) {
251:     const m = new THREE.Mesh(new THREE.CylinderGeometry(r, r, h, seg), mat);
252:     m.position.set(x, y, z);
253:     m.castShadow = cast;
254:     m.receiveShadow = true;
255:     this.scene.add(m);
256:     if (solid) this.colliders.push(new THREE.Box3(V(x - r, y - h / 2, z - r), V(x + r, y + h / 2, z + r)));
257:     this.meshes.push(m);
258:     return m;
259:   }
