512:     const g = new THREE.Group();
513:     g.position.copy(pos);
514:     const spin = new THREE.Group();
515:     g.add(spin);
516:     let lightColor = 0x51ffb0;
517:     let lightScale = 2.1;
518:     let respawn = 18;
519:     let label = type;
520: 
521:     if (type === 'health') {
522:       const mat = new THREE.MeshBasicMaterial({ color: 0xff3b5c });
523:       const a = new THREE.Mesh(new THREE.BoxGeometry(0.95, 0.3, 0.3), mat);
524:       const b = new THREE.Mesh(new THREE.BoxGeometry(0.3, 0.95, 0.3), mat);
