531:       spin.add(a, b);
532:       const orb = new THREE.Mesh(new THREE.IcosahedronGeometry(0.62, 1), new THREE.MeshBasicMaterial({ color: 0x51ffb0, wireframe: true, transparent: true, opacity: 0.6 }));
533:       orb.scale.setScalar(1.5);
534:       spin.add(orb);
535:       lightColor = 0x51ffb0; lightScale = 3.4; respawn = 32;
536:     } else if (type === 'armor') {
537:       const m = new THREE.Mesh(new THREE.OctahedronGeometry(0.52, 0), new THREE.MeshStandardMaterial({ color: 0x58ffe0, emissive: 0x1a9a7a, emissiveIntensity: 2, metalness: 0.3, roughness: 0.25 }));
538:       m.scale.set(0.85, 1.25, 0.55);
539:       spin.add(m);
540:       const w = new THREE.Mesh(new THREE.OctahedronGeometry(0.56, 0), new THREE.MeshBasicMaterial({ color: 0xacfff0, wireframe: true, transparent: true, opacity: 0.55 }));
541:       w.scale.set(0.85, 1.25, 0.55);
542:       spin.add(w);
543:       lightColor = 0x51ffb0; lightScale = 2.4;
544:     } else if (type === 'rockets') {
545:       for (let i = -1; i <= 1; i++) {
546:         const m = new THREE.Mesh(new THREE.CylinderGeometry(0.1, 0.13, 0.85, 8), new THREE.MeshStandardMaterial({ color: 0xffb02e, emissive: 0xff6a00, emissiveIntensity: 1.4, roughness: 0.4, metalness: 0.6 }));
547:         m.position.set(i * 0.3, 0, 0);
548:         m.rotation.z = i * 0.2;
549:         spin.add(m);
550:         const tip = new THREE.Mesh(new THREE.ConeGeometry(0.13, 0.24, 8), new THREE.MeshBasicMaterial({ color: 0xffe0a0 }));
551:         tip.position.set(i * 0.3, 0.55, 0);
552:         spin.add(tip);
553:       }
554:       lightColor = 0xffb02e; respawn = 14;
555:     } else if (type === 'rails') {
556:       const m = new THREE.Mesh(new THREE.CylinderGeometry(0.18, 0.18, 1.15, 6), new THREE.MeshStandardMaterial({ color: 0x65f4ff, emissive: 0x22c7ff, emissiveIntensity: 2.4, metalness: 0.7, roughness: 0.2 }));
557:       spin.add(m);
558:       for (const yy of [-0.32, 0.32]) {
559:         const r = new THREE.Mesh(new THREE.TorusGeometry(0.25, 0.04, 5, 16), M.cyan);
560:         r.rotation.x = Math.PI / 2; r.position.y = yy; spin.add(r);
561:       }
562:       lightColor = 0x3fe9ff; respawn = 16;
563:     } else if (type === 'discs') {
564:       const disc = new THREE.Mesh(new THREE.CylinderGeometry(0.42, 0.42, 0.08, 22), new THREE.MeshStandardMaterial({ color: 0x8fe9ff, emissive: 0x2a9fc4, emissiveIntensity: 1.8, metalness: 0.75, roughness: 0.25 }));
565:       disc.rotation.x = Math.PI / 2;
