814: // Shared capsule-ish movement for player and bots.
815: export function moveBody(body, world, dt, { stepHeight = 0.55, gravity = 26 } = {}) {
816:   const pos = body.position;
817:   const vel = body.velocity;
818:   const radius = body.radius;
819:   const height = body.height;
820:   let grounded = false;
821: 
822:   // horizontal, axis separated with step-up
823:   for (const axis of ['x', 'z']) {
824:     if (Math.abs(vel[axis]) < 0.0001) continue;
825:     const amount = vel[axis] * dt;
826:     const old = pos[axis];
827:     pos[axis] += amount;
828:     if (world.overlaps(pos, radius, height)) {
829:       // try step up
830:       const oldY = pos.y;
831:       pos.y += stepHeight;
832:       if (!world.overlaps(pos, radius, height)) {
833:         // keep lifted position, will settle on the step
834:       } else {
835:         pos.y = oldY;
836:         pos[axis] = old;
837:         // step out a hair to avoid sticking
838:         pos[axis] += Math.sign(amount) * 0.001;
839:         vel[axis] = 0;
840:       }
841:     }
842:   }
843: 
844:   // vertical
845:   vel.y -= gravity * dt;
846:   if (vel.y < -60) vel.y = -60;
847:   const oldY = pos.y;
848:   pos.y += vel.y * dt;
849:   const hit = world.overlaps(pos, radius, height);
850:   if (hit) {
851:     if (vel.y <= 0) {
852:       pos.y = hit.max.y;
853:       grounded = true;
854:       if (body.onLand && vel.y < -3) body.onLand(-vel.y);
855:     } else {
856:       pos.y = hit.min.y - height;
857:     }
858:     vel.y = 0;
859:   }
860:   // ground probe (standing still / step edges)
861:   if (!grounded && Math.abs(vel.y) < 0.5) {
862:     const top = world.groundHeight(pos.x, pos.z, pos.y + 0.12);
863:     if (top > -Infinity && pos.y - top < 0.12) {
864:       pos.y = top;
865:       grounded = true;
866:     }
867:   }
868: 
869:   // world bounds / kill floor
870:   body.grounded = grounded;
871:   if (pos.y < -24) body.fellOut = true;
872:   return grounded;
873: }

