/* ---------------- Screens ---------------- */
.screen{position:absolute;inset:0;z-index:30;pointer-events:auto}
.menu-screen{display:flex;flex-direction:column;background:
  radial-gradient(1000px 700px at 72% 48%,rgba(0,0,0,0) 20%,rgba(4,1,10,.65) 78%),
  linear-gradient(100deg,rgba(4,1,10,.96) 0%,rgba(4,1,10,.86) 30%,rgba(4,1,10,.34) 62%,rgba(4,1,10,.5) 100%)}
.menu-screen::after{content:"";position:absolute;inset:0;pointer-events:none;background:repeating-linear-gradient(0deg,rgba(255,255,255,.025) 0 1px,transparent 1px 3px);mix-blend-mode:overlay;opacity:.35}
.menu-veil{position:absolute;inset:0;pointer-events:none;background:radial-gradient(900px 500px at 78% 62%,rgba(255,46,138,.12),transparent 60%),radial-gradient(700px 500px at 64% 20%,rgba(63,233,255,.09),transparent 65%)}
.menu-top{position:relative;z-index:2;display:flex;justify-content:space-between;align-items:center;padding:26px 4.5vw 0 calc(4.5vw + var(--safe-l));font-family:var(--display);font-size:10px;letter-spacing:.2em;color:#7f93ab}
.brandmark{font-size:15px;letter-spacing:.28em;color:#e8f6ff;font-weight:700;display:flex;align-items:center;gap:9px}
.brand-glyph{color:var(--cyan);font-size:18px;text-shadow:0 0 14px var(--cyan);animation:pulse 3s infinite}
.brand-thin{color:#5d728a;font-weight:400;letter-spacing:.14em}
.menu-meta{display:flex;align-items:center;gap:14px}
.meta-dot{width:4px;height:4px;border-radius:50%;background:var(--cyan);box-shadow:0 0 8px var(--cyan)}
.sig{color:var(--green)}

.menu-main{position:relative;z-index:2;flex:1;display:grid;grid-template-columns:minmax(0,1.15fr) minmax(300px,.62fr);gap:3vw;align-items:center;padding:0 5vw calc(var(--safe-b) + 20px) calc(5vw + var(--safe-l))}
.hero{max-width:780px}
.hero h1{font-family:var(--display);font-weight:900;font-style:italic;font-size:clamp(72px,11.5vw,178px);line-height:.82;letter-spacing:-.055em;margin:14px 0 8px;position:relative;color:#f3f8ff;
  text-shadow:0 0 40px rgba(63,233,255,.35),0 0 100px rgba(255,46,138,.22);transform:skewX(-4deg)}
.hero h1 span{display:inline-block;margin-left:.08em;background:linear-gradient(180deg,#a9f8ff 5%,#3fe9ff 45%,#0e7d9c 100%);-webkit-background-clip:text;background-clip:text;color:transparent;text-shadow:none;filter:drop-shadow(0 0 22px rgba(63,233,255,.5));font-size:.72em;vertical-align:.08em}
.hero-sub{font-family:var(--display);font-size:clamp(13px,1.4vw,19px);letter-spacing:.42em;color:#dbefff;font-weight:500;margin:4px 0 18px}
.hero-sub b{color:var(--mag);text-shadow:0 0 12px var(--mag)}
.hero-copy{font-size:clamp(15px,1.3vw,19px);line-height:1.45;color:#a9bccf;max-width:520px;font-weight:500;letter-spacing:.01em;border-left:2px solid rgba(63,233,255,.35);padding-left:16px}
.menu-actions{display:flex;gap:14px;margin:28px 0 30px;align-items:stretch}

.btn-primary{position:relative;min-width:236px;padding:17px 26px;background:linear-gradient(100deg,#28d7f2,#3fe9ff 45%,#9ff8ff);color:#04121a;font-family:var(--display);font-weight:900;font-size:15px;letter-spacing:.22em;display:flex;align-items:center;justify-content:space-between;gap:18px;
  clip-path:polygon(0 0,100% 0,100% calc(100% - 14px),calc(100% - 14px) 100%,0 100%);box-shadow:0 0 34px rgba(63,233,255,.38),inset 0 -4px 0 rgba(0,30,40,.25);transition:filter .16s,transform .16s}
.btn-primary:hover{filter:brightness(1.15) saturate(1.1);transform:translateY(-2px)}
.btn-primary:active{transform:translateY(0)}
.btn-primary i{font-style:normal;font-size:19px;transition:transform .16s}
.btn-primary:hover i{transform:translateX(4px)}
.btn-ghost{font-family:var(--display);font-size:11px;letter-spacing:.22em;padding:0 24px;border:1px solid rgba(120,200,255,.3);color:#a9c8dc;background:linear-gradient(180deg,rgba(20,40,60,.4),rgba(8,16,28,.4));clip-path:polygon(0 0,100% 0,100% calc(100% - 10px),calc(100% - 10px) 100%,0 100%);transition:.16s}
.btn-ghost:hover{border-color:var(--cyan);color:#e9fbff;box-shadow:0 0 22px rgba(63,233,255,.18) inset}
.quick-stats{display:flex;gap:clamp(20px,3.2vw,46px)}
.quick-stats div{display:flex;flex-direction:column;gap:4px;border-top:1px solid rgba(120,200,255,.22);padding-top:8px;min-width:70px}
.quick-stats b{font-family:var(--display);font-size:20px;color:#eafcff;letter-spacing:.06em}
.quick-stats span{font-family:var(--display);font-size:8.5px;letter-spacing:.2em;color:#6f8aa3}

.menu-card{position:relative;background:linear-gradient(160deg,rgba(13,16,36,.84),rgba(7,8,20,.9));border:1px solid rgba(100,180,255,.2);padding:18px;clip-path:polygon(0 0,calc(100% - 18px) 0,100% 18px,100% 100%,18px 100%,0 calc(100% - 18px));box-shadow:0 30px 80px rgba(0,0,0,.55),inset 0 0 60px rgba(63,233,255,.045);backdrop-filter:blur(10px)}
.card-head{display:flex;justify-content:space-between;font-family:var(--display);font-size:9.5px;letter-spacing:.2em;color:#7896ae;padding-bottom:12px;border-bottom:1px solid rgba(100,180,255,.13)}
.card-head em{color:var(--cyan);font-style:normal}
.card-map{position:relative;height:170px;margin:14px 0;background:radial-gradient(circle at 50% 50%,rgba(63,233,255,.08),transparent 65%),#070b16;border:1px solid rgba(63,233,255,.16);overflow:hidden;clip-path:polygon(0 0,100% 0,100% 100%,12px 100%,0 calc(100% - 12px))}
.map-grid{position:absolute;inset:0;background-image:linear-gradient(rgba(63,233,255,.1) 1px,transparent 1px),linear-gradient(90deg,rgba(63,233,255,.1) 1px,transparent 1px);background-size:22px 22px;transform:perspective(300px) rotateX(52deg) scale(1.5);opacity:.6}
.map-center{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);color:var(--amber);font-size:22px;text-shadow:0 0 20px var(--amber);animation:pulse 2.4s infinite}
.map-blip{position:absolute;width:8px;height:8px;border-radius:50%;background:var(--mag);box-shadow:0 0 12px var(--mag)}
.b1{left:28%;top:34%}.b2{left:68%;top:62%}.b3{left:61%;top:26%;background:var(--cyan);box-shadow:0 0 12px var(--cyan)}
.b1::after,.b2::after,.b3::after{content:"";position:absolute;inset:-5px;border:1px solid currentColor;border-radius:50%;opacity:.4;animation:ping 2.6s infinite}
.map-scan{position:absolute;left:0;right:0;height:28%;background:linear-gradient(180deg,transparent,rgba(63,233,255,.12),transparent);animation:scan 4s linear infinite}
.brief-list{list-style:none;display:flex;flex-direction:column;gap:13px;margin:16px 0 18px}
.brief-list li{display:grid;grid-template-columns:28px 1fr;gap:10px;align-items:start}
.brief-list li>span{font-family:var(--display);font-size:10px;color:var(--cyan);padding-top:2px;opacity:.8}
.brief-list p{font-size:13.5px;line-height:1.35;color:#93a9bd;font-weight:500}
.brief-list b{display:block;font-family:var(--display);font-size:10px;letter-spacing:.14em;color:#dcefff;margin-bottom:2px}
.card-foot{font-family:var(--display);font-size:8.5px;letter-spacing:.16em;color:#6b869e;border-top:1px solid rgba(100,180,255,.13);padding-top:11px;display:flex;align-items:center;gap:7px}
.ready-dot{width:5px;height:5px;border-radius:50%;background:var(--green);box-shadow:0 0 9px var(--green);animation:pulse 1.6s infinite}

.menu-foot{position:relative;z-index:2;display:flex;justify-content:space-between;align-items:center;gap:20px;padding:14px 4.5vw calc(18px + var(--safe-b)) calc(4.5vw + var(--safe-l));border-top:1px solid rgba(100,180,255,.12);background:linear-gradient(180deg,transparent,rgba(3,1,9,.6))}
.control-ribbon{display:flex;flex-wrap:wrap;gap:8px 18px;font-family:var(--display);font-size:8.5px;letter-spacing:.14em;color:#6d8399}
.control-ribbon span{display:flex;align-items:center;gap:6px}
.menu-settings{display:flex;align-items:center;gap:16px;font-family:var(--display);font-size:9px;letter-spacing:.14em;color:#788fa4}
.menu-settings label{display:flex;align-items:center;gap:9px}
.menu-settings b{color:var(--cyan);font-weight:500;min-width:28px}
input[type=range]{-webkit-appearance:none;appearance:none;width:88px;height:2px;background:rgba(120,200,255,.28);outline:none}
input[type=range]::-webkit-slider-thumb{-webkit-appearance:none;width:10px;height:14px;background:var(--cyan);box-shadow:0 0 10px rgba(63,233,255,.7);cursor:pointer}
.mini-btn{font-family:var(--display);font-size:9px;letter-spacing:.14em;color:#b9d7e8;border:1px solid rgba(120,200,255,.26);padding:7px 10px;transition:.15s}
.mini-btn:hover{border-color:var(--cyan);color:#fff;background:rgba(63,233,255,.08)}

.controls-panel{position:absolute;z-index:6;right:5vw;top:50%;transform:translateY(-50%);width:min(520px,86vw);background:rgba(6,8,20,.97);border:1px solid rgba(63,233,255,.28);padding:26px;box-shadow:0 30px 90px rgba(0,0,0,.8);clip-path:polygon(0 0,calc(100% - 20px) 0,100% 20px,100% 100%,20px 100%,0 calc(100% - 20px))}
.controls-panel h3{font-family:var(--display);font-size:16px;letter-spacing:.22em;margin-bottom:18px;color:#e9faff}
.panel-close{position:absolute;right:16px;top:10px;font-size:26px;color:#7e9ab0;line-height:1}
.panel-close:hover{color:var(--mag)}
.ctrl-grid{display:grid;grid-template-columns:1fr 1fr;gap:11px 18px}
.ctrl-grid div{display:flex;align-items:center;gap:10px;font-size:13px;color:#95abc0;font-weight:500}
.ctrl-grid kbd{min-width:66px;text-align:center;flex:none}
.manual-note{font-size:12.5px;color:#6d849a;margin-top:18px;padding-top:14px;border-top:1px solid rgba(100,180,255,.14);line-height:1.4}

/* ---------------- HUD ---------------- */
#hud{position:absolute;inset:0;z-index:20;pointer-events:none;font-family:var(--ui)}
.fx-vignette{position:absolute;inset:0;pointer-events:none;background:radial-gradient(ellipse at center,transparent 48%,rgba(2,0,8,.5) 85%,rgba(0,0,0,.82) 100%);transition:box-shadow .2s}
.fx-quad{position:absolute;inset:0;pointer-events:none;opacity:0;background:radial-gradient(ellipse at center,transparent 45%,rgba(255,176,46,.12) 78%,rgba(255,46,138,.34) 100%);transition:opacity .3s}
.fx-quad.on{opacity:1;animation:quadPulse 1.1s ease-in-out infinite}
.fx-scanlines{position:absolute;inset:0;pointer-events:none;background:repeating-linear-gradient(0deg,rgba(255,255,255,.03) 0 1px,transparent 1px 3px);opacity:.22;mix-blend-mode:overlay}
.fx-damage{position:absolute;inset:0;pointer-events:none;opacity:0;background:radial-gradient(ellipse at center,transparent 40%,rgba(255,32,64,.28) 72%,rgba(255,20,50,.62) 100%);transition:opacity .16s}
.damage-dirs{position:absolute;inset:0;pointer-events:none}
.hitmarker i:nth-child(2){transform:rotate(135deg) translateY(-22px)}
.hitmarker i:nth-child(3){transform:rotate(225deg) translateY(-22px)}
.hitmarker i:nth-child(4){transform:rotate(315deg) translateY(-22px)}
.hitmarker.show{animation:hitIn .25s ease-out}
.hitmarker-kill i{background:var(--mag);box-shadow:0 0 8px var(--mag);height:12px}
.hitmarker-kill.show{animation:hitIn .45s ease-out}

.target-tag{position:absolute;left:50%;top:calc(50% - 44px);transform:translateX(-50%);text-align:center;width:120px}
.target-tag b{font-family:var(--display);font-size:8.5px;letter-spacing:.2em;color:#f1fbff;text-shadow:0 1px 4px #000}
.target-tag span{display:block;height:3px;background:rgba(0,0,0,.6);border:1px solid rgba(255,255,255,.25);margin-top:4px}
.target-tag i{display:block;height:100%;background:linear-gradient(90deg,var(--red),var(--mag));transition:width .1s;width:100%}

.objective{position:absolute;top:86px;left:50%;transform:translateX(-50%);width:210px;text-align:center;font-family:var(--display)}
.obj-kicker{font-size:7.5px;letter-spacing:.24em;color:#8a7a5b}
.obj-track{height:3px;background:rgba(255,176,46,.12);margin:5px 0 3px;overflow:hidden}
.obj-track i{display:block;height:100%;width:0;background:linear-gradient(90deg,var(--amber),var(--mag));box-shadow:0 0 10px var(--amber);transition:width .2s}
.obj-state{font-size:6.5px;letter-spacing:.22em;color:#695f4b}
.objective.live .obj-state{color:var(--amber);text-shadow:0 0 10px rgba(255,176,46,.5)}

.vitals{position:absolute;left:calc(26px + var(--safe-l));bottom:calc(26px + var(--safe-b));display:flex;flex-direction:column;gap:8px}
.vital{display:flex;align-items:center;gap:10px;background:linear-gradient(90deg,rgba(9,12,26,.82),rgba(9,12,26,.25));border-left:2px solid rgba(255,255,255,.25);padding:6px 18px 6px 7px;min-width:214px;clip-path:polygon(0 0,100% 0,100% 100%,8px 100%,0 calc(100% - 8px))}
.vital.health{border-left-color:var(--red)}
.vital.armor{border-left-color:var(--cyan)}
.vital-icon{width:30px;height:30px;display:grid;place-items:center;flex:none}
.vital-icon svg{width:21px;height:21px;fill:none;stroke:currentColor;stroke-width:1.6}
.health .vital-icon{color:var(--red);filter:drop-shadow(0 0 6px rgba(255,59,78,.5))}
.armor .vital-icon{color:var(--cyan);filter:drop-shadow(0 0 6px rgba(63,233,255,.5))}
.vital-body{flex:1;display:grid;grid-template-columns:1fr auto;align-items:center;gap:0 8px}
.vital-label{font-family:var(--display);font-size:7.5px;letter-spacing:.22em;color:#7d90a4;grid-column:1}
.vital-value{font-family:var(--display);font-size:28px;font-weight:700;line-height:.9;color:#f4fcff;grid-column:2;grid-row:1/3;text-shadow:0 0 16px rgba(255,255,255,.18);min-width:56px;text-align:right}
.vital-bar{grid-column:1;height:3px;background:rgba(255,255,255,.1);margin-top:3px;overflow:hidden}
.vital-bar i{display:block;height:100%;width:100%;transition:width .18s}
.health .vital-bar i{background:linear-gradient(90deg,#ff3b4e,#ff7a5c);box-shadow:0 0 8px rgba(255,59,78,.7)}
.armor .vital-bar i{background:linear-gradient(90deg,#1a9bb5,#3fe9ff);box-shadow:0 0 8px rgba(63,233,255,.7)}
.vitals.low .health .vital-value{color:var(--red);animation:lowPulse .8s infinite}

.center-bottom{position:absolute;left:50%;bottom:calc(28px + var(--safe-b));transform:translateX(-50%);display:flex;flex-direction:column;align-items:center;gap:8px;width:min(430px,42vw)}
.fuel-wrap{width:100%}
.fuel-label{display:flex;justify-content:space-between;font-family:var(--display);font-size:7.5px;letter-spacing:.2em;color:#7d93a8;margin-bottom:4px}
.fuel-label em{font-style:normal;color:#5f7488;transition:.2s}
.fuel-label em.hot{color:var(--green);text-shadow:0 0 10px rgba(81,255,176,.5)}
.fuel-track{position:relative;height:7px;background:rgba(8,12,24,.8);border:1px solid rgba(100,180,255,.2);transform:skewX(-22deg);overflow:hidden}
.fuel-track i{display:block;height:100%;width:100%;background:linear-gradient(90deg,#1a9bb5,#3fe9ff 65%,#b7fbff);box-shadow:0 0 12px rgba(63,233,255,.65);transition:width .08s}
.fuel-track i.low{background:linear-gradient(90deg,#a93700,#ffb02e);box-shadow:0 0 12px rgba(255,176,46,.6)}
.fuel-ticks{position:absolute;inset:0;background:repeating-linear-gradient(90deg,transparent 0 17px,rgba(4,8,16,.9) 17px 19px)}
.weapon-name{text-align:center;font-family:var(--display);line-height:1}
.weapon-name b{font-size:13px;letter-spacing:.2em;color:#f1fbff;text-shadow:0 0 14px rgba(63,233,255,.35)}
.weapon-name span{display:block;font-size:6.5px;letter-spacing:.18em;color:#61778b;margin-top:4px}

.weapon-panel{position:absolute;right:calc(26px + var(--safe-r));bottom:calc(26px + var(--safe-b));display:flex;flex-direction:column;align-items:flex-end;gap:8px}
.ammo-block{display:flex;align-items:flex-end;gap:10px;background:linear-gradient(270deg,rgba(9,12,26,.82),rgba(9,12,26,.2));border-right:2px solid var(--cyan);padding:3px 14px 4px 24px;clip-path:polygon(0 0,100% 0,100% calc(100% - 8px),calc(100% - 8px) 100%,0 100%)}
.ammo-value{font-family:var(--display);font-size:40px;font-weight:700;line-height:.9;color:#f4fdff;min-width:62px;text-align:right;text-shadow:0 0 18px rgba(63,233,255,.3)}
.ammo-info{display:flex;flex-direction:column;align-items:flex-start;gap:2px;padding-bottom:3px}
.ammo-info span{font-family:var(--display);font-size:8px;letter-spacing:.18em;color:#7b91a5}
.ammo-info em{font-style:normal;font-family:var(--display);font-size:7px;letter-spacing:.12em;color:var(--red);min-height:9px}
.weapon-slots{display:flex;gap:4px}
.slot{position:relative;pointer-events:auto;width:62px;background:rgba(8,12,24,.72);border:1px solid rgba(100,170,230,.16);padding:5px 4px 6px;display:flex;flex-direction:column;gap:1px;transition:.15s;overflow:hidden;cursor:pointer}
.slot b{font-family:var(--display);font-size:8px;color:#5f7488}
.slot span{font-family:var(--display);font-size:6px;letter-spacing:.1em;color:#8ba0b4}
.slot .slot-fill{position:absolute;left:0;right:0;bottom:0;height:2px;background:rgba(63,233,255,.35);transform:scaleX(var(--f,1));transform-origin:left;transition:transform .15s}
.slot.active{border-color:var(--cyan);background:linear-gradient(180deg,rgba(30,90,110,.55),rgba(10,26,38,.8));box-shadow:0 0 18px rgba(63,233,255,.18),inset 0 0 16px rgba(63,233,255,.08)}
.slot.active b{color:var(--cyan)}.slot.active span{color:#f0fdff}
.slot.empty{opacity:.4}
.slot.empty .slot-fill{background:var(--red)}

.radar-wrap{position:absolute;right:calc(26px + var(--safe-r));bottom:calc(160px + var(--safe-b));width:176px;pointer-events:none}
.radar-head{display:flex;justify-content:space-between;font-family:var(--display);font-size:6.5px;letter-spacing:.16em;color:#71879b;margin-bottom:4px}
.radar-head em{font-style:normal;color:var(--mag)}
#radar{width:176px;height:176px;border:1px solid rgba(63,233,255,.18);background:rgba(4,8,16,.42);clip-path:polygon(0 0,calc(100% - 12px) 0,100% 12px,100% 100%,12px 100%,0 calc(100% - 12px));opacity:.9}
.score-strip{position:absolute;left:calc(26px + var(--safe-l));bottom:calc(130px + var(--safe-b));display:flex;align-items:center;gap:10px;font-family:var(--display);font-size:8px;letter-spacing:.16em;color:#6f8498}
.score-strip b{color:#e8f9ff;font-weight:500;font-size:12px;margin-left:3px}
.score-sep{width:1px;height:10px;background:rgba(120,200,255,.25)}

.pointer-hint{position:absolute;left:50%;bottom:150px;transform:translateX(-50%);font-family:var(--display);font-size:8px;letter-spacing:.22em;color:rgba(210,240,255,.65);background:rgba(6,10,22,.6);border:1px solid rgba(100,180,255,.18);padding:7px 14px;animation:pulse 2.5s infinite}

.respawn-overlay{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;background:radial-gradient(ellipse at center,rgba(30,0,12,.28),rgba(3,0,8,.78));backdrop-filter:blur(2px)}
.respawn-title{font-family:var(--display);font-size:clamp(24px,3vw,42px);font-style:italic;font-weight:900;letter-spacing:.1em;color:#ffe8ec;text-shadow:0 0 30px rgba(255,46,90,.65)}
.respawn-sub{font-family:var(--display);font-size:9px;letter-spacing:.32em;color:#ff8aa2;margin-top:8px}
.respawn-count{display:flex;align-items:center;gap:12px;margin-top:26px}
.respawn-count b{font-family:var(--display);font-size:42px;color:#fff;line-height:1;text-shadow:0 0 20px rgba(63,233,255,.6)}
.respawn-count span{font-family:var(--display);font-size:8px;letter-spacing:.24em;color:#7c94a8;line-height:1.3;max-width:50px}

.scoreboard{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);width:min(620px,88vw);background:linear-gradient(160deg,rgba(8,11,24,.97),rgba(5,6,16,.98));border:1px solid rgba(63,233,255,.25);padding:20px 22px;box-shadow:0 40px 100px rgba(0,0,0,.75);clip-path:polygon(0 0,calc(100% - 18px) 0,100% 18px,100% 100%,18px 100%,0 calc(100% - 18px))}
.sb-head{display:flex;justify-content:space-between;font-family:var(--display);font-size:11px;letter-spacing:.24em;color:#e9fbff;border-bottom:1px solid rgba(100,180,255,.2);padding-bottom:10px}
.sb-head em{font-style:normal;color:var(--cyan)}
.sb-cols,.sb-row{display:grid;grid-template-columns:30px 1fr 70px 70px 70px;gap:6px;align-items:center}
.sb-cols{font-family:var(--display);font-size:7px;letter-spacing:.18em;color:#617a90;padding:10px 4px 6px}
.sb-cols span:not(:nth-child(2)),.sb-row span:not(.sb-name){text-align:center}
.sb-row{font-family:var(--display);font-size:10px;letter-spacing:.06em;color:#a9bfd1;padding:9px 4px;border-bottom:1px solid rgba(100,180,255,.08)}
.sb-row.you{background:linear-gradient(90deg,rgba(63,233,255,.1),rgba(63,233,255,.02));color:#effdff;box-shadow:inset 2px 0 0 var(--cyan)}
.sb-rank{color:#6d8398;font-size:9px}
.sb-row.you .sb-rank{color:var(--cyan)}
.sb-name{display:flex;align-items:center;gap:8px}
.sb-name i{width:7px;height:7px;border-radius:50%;display:inline-block;box-shadow:0 0 8px currentColor}
.sb-frags{font-size:14px;color:#fff}
.sb-row.you .sb-frags{color:var(--cyan)}
.sb-foot{font-family:var(--display);font-size:7px;letter-spacing:.16em;color:#5a7186;margin-top:12px;text-align:right}
.sb-foot b{color:var(--amber)}

/* ---------------- Pause / Game over ---------------- */
.pause-screen{display:grid;place-items:center;background:rgba(3,1,9,.66);backdrop-filter:blur(9px)}
.pause-card{width:min(500px,90vw);background:linear-gradient(160deg,rgba(11,14,30,.96),rgba(5,6,16,.98));border:1px solid rgba(63,233,255,.25);padding:32px;clip-path:polygon(0 0,calc(100% - 22px) 0,100% 22px,100% 100%,22px 100%,0 calc(100% - 22px));box-shadow:0 40px 100px rgba(0,0,0,.8)}
.pause-card h2{font-family:var(--display);font-size:clamp(38px,5vw,62px);font-weight:900;font-style:italic;line-height:.9;letter-spacing:-.02em;margin:16px 0 22px;color:#f4fcff;text-shadow:0 0 40px rgba(63,233,255,.25)}
.pause-score{display:flex;gap:24px;border-top:1px solid rgba(100,180,255,.14);border-bottom:1px solid rgba(100,180,255,.14);padding:12px 0;margin-bottom:22px;font-family:var(--display);font-size:8px;letter-spacing:.18em;color:#738ba1}
.pause-score b{display:block;font-size:16px;color:#eafbff;margin-top:3px;letter-spacing:.06em}
.pause-actions{display:flex;flex-direction:column;gap:9px}
.pause-actions .btn-primary{width:100%;justify-content:space-between;min-width:0}
.pause-actions .btn-ghost{padding:11px 18px;text-align:left}
.pause-settings{display:flex;justify-content:space-between;align-items:center;gap:14px;margin-top:22px;font-family:var(--display);font-size:8.5px;letter-spacing:.14em;color:#7a91a6}
.pause-settings label{display:flex;align-items:center;gap:8px}
.pause-settings b{color:var(--cyan);min-width:28px}
.pause-tip{font-size:12px;line-height:1.4;color:#6b8298;margin-top:18px;border-left:2px solid rgba(255,176,46,.4);padding-left:10px;letter-spacing:.02em}

.gameover-screen{display:grid;place-items:center;background:radial-gradient(ellipse at center,rgba(12,4,30,.7),rgba(2,0,7,.94))}
.go-veil{position:absolute;inset:0;background:linear-gradient(120deg,rgba(255,46,138,.1),transparent 45%,rgba(63,233,255,.08));pointer-events:none}
.go-card{position:relative;width:min(660px,92vw);background:linear-gradient(160deg,rgba(10,12,28,.96),rgba(4,5,14,.98));border:1px solid rgba(63,233,255,.28);padding:32px 34px;clip-path:polygon(0 0,calc(100% - 24px) 0,100% 24px,100% 100%,24px 100%,0 calc(100% - 24px));box-shadow:0 50px 140px rgba(0,0,0,.85);max-height:92vh;overflow:auto}
.go-card h2{font-family:var(--display);font-size:clamp(44px,7vw,82px);font-weight:900;font-style:italic;line-height:.9;letter-spacing:-.02em;margin:14px 0 8px;color:#f8feff;text-shadow:0 0 50px rgba(63,233,255,.35)}
.go-card.lost h2{color:#ffe9ed;text-shadow:0 0 50px rgba(255,46,90,.45)}
.go-card p{font-size:15px;color:#93a9bd;margin-bottom:20px}
.go-score{display:flex;gap:30px;border-top:1px solid rgba(100,180,255,.16);border-bottom:1px solid rgba(100,180,255,.16);padding:12px 0;margin-bottom:16px;font-family:var(--display);font-size:8px;letter-spacing:.18em;color:#6f879d}
.go-score b{display:block;font-size:18px;color:#eafcff;margin-top:2px}
.go-rows{display:flex;flex-direction:column;gap:1px;margin-bottom:22px}
.go-row{display:grid;grid-template-columns:28px 1fr 52px 52px;gap:8px;font-family:var(--display);font-size:9px;letter-spacing:.06em;padding:7px 6px;color:#94aabd;background:rgba(255,255,255,.02)}
.go-row.you{color:#eafcff;background:rgba(63,233,255,.08)}
.go-row b{font-size:12px;color:#fff;font-weight:500}
.go-row.you b{color:var(--cyan)}

/* ---------------- Touch ---------------- */
.touch-controls{display:none;position:absolute;inset:0;pointer-events:none}
.stick-zone{position:absolute;left:calc(20px + var(--safe-l));bottom:calc(22px + var(--safe-b));width:132px;height:132px;pointer-events:auto;touch-action:none}
.stick-base{position:absolute;inset:0;border:1.5px solid rgba(63,233,255,.28);border-radius:50%;background:radial-gradient(circle,rgba(63,233,255,.08),rgba(4,8,16,.35));box-shadow:inset 0 0 30px rgba(63,233,255,.06)}
.stick-base::before{content:"";position:absolute;left:50%;top:50%;width:64%;height:1px;background:rgba(63,233,255,.12);transform:translate(-50%,-50%)}
.stick-base::after{content:"";position:absolute;left:50%;top:50%;height:64%;width:1px;background:rgba(63,233,255,.12);transform:translate(-50%,-50%)}
.stick-knob{position:absolute;left:50%;top:50%;width:52px;height:52px;margin:-26px 0 0 -26px;border-radius:50%;background:radial-gradient(circle at 35% 30%,rgba(190,250,255,.55),rgba(30,120,150,.5));border:1.5px solid rgba(140,240,255,.6);box-shadow:0 0 22px rgba(63,233,255,.35);transition:transform .05s}
.look-zone{position:absolute;right:0;top:12%;width:52%;height:64%;pointer-events:auto;touch-action:none;display:grid;place-items:center}
.look-zone span{font-family:var(--display);font-size:7px;letter-spacing:.3em;color:rgba(150,210,240,.14);border:1px dashed rgba(150,210,240,.12);border-radius:50%;padding:34px 22px}
.touch-actions{position:absolute;right:calc(18px + var(--safe-r));bottom:calc(20px + var(--safe-b));display:flex;align-items:flex-end;gap:10px;pointer-events:none}
.t-btn{pointer-events:auto;touch-action:none;border-radius:50%;display:flex;flex-direction:column;align-items:center;justify-content:center;font-family:var(--display);border:1.5px solid rgba(63,233,255,.4);background:radial-gradient(circle at 35% 30%,rgba(40,180,210,.28),rgba(5,12,20,.5));color:#e8fcff;box-shadow:0 0 24px rgba(63,233,255,.12),inset 0 0 18px rgba(63,233,255,.08)}
.t-btn:active{background:rgba(63,233,255,.32)}
.t-btn span{font-size:11px;letter-spacing:.12em}
.t-btn small{font-size:5.5px;letter-spacing:.14em;opacity:.55;margin-top:2px}
.t-fire{width:88px;height:88px;border-color:rgba(255,70,110,.6);background:radial-gradient(circle at 35% 30%,rgba(255,70,110,.34),rgba(30,4,12,.55));color:#ffe9ed;box-shadow:0 0 30px rgba(255,46,90,.2)}
.t-jump{width:70px;height:70px;margin-bottom:38px}
.t-weapon{width:54px;height:54px;margin-bottom:82px;border-color:rgba(255,176,46,.45);color:#ffdf9e}
.t-pause{position:absolute;right:calc(20px + var(--safe-r));top:calc(14px + env(safe-area-inset-top,0px));width:38px;height:38px;border-radius:6px;font-size:11px;pointer-events:auto}
body.touch .touch-controls{display:block}
body.touch .crosshair{top:46%}
body.touch .vitals{top:calc(86px + env(safe-area-inset-top,0px));left:calc(14px + var(--safe-l));bottom:auto;transform:scale(.82);transform-origin:top left;gap:5px}
body.touch .weapon-panel{top:calc(86px + env(safe-area-inset-top,0px));right:calc(14px + var(--safe-r));bottom:auto;transform:scale(.82);transform-origin:top right}
body.touch .weapon-name,body.touch .radar-wrap,body.touch .score-strip,body.touch .objective,body.touch .pointer-hint{display:none}
body.touch .center-bottom{bottom:calc(176px + var(--safe-b));width:min(300px,56vw)}
body.touch .match-bar{top:calc(8px + env(safe-area-inset-top,0px));width:calc(100vw - 100px);max-width:420px}
body.touch .match-mode em,body.touch .match-clock small,body.touch .match-limit small{display:none}
body.touch .match-clock{padding:5px 12px !important}.match-clock span{font-size:17px}
body.touch .match-limit{padding:5px 12px !important}.match-limit span{font-size:17px}
body.touch .match-mode{padding:6px 10px}.match-mode b{font-size:9px}
body.touch .killfeed{top:calc(64px + env(safe-area-inset-top,0px));right:calc(12px + var(--safe-r));max-width:250px}
body.touch .kf-row{font-size:8px;padding:3px 6px}
body.touch .ammo-value{font-size:32px}
body.touch .weapon-slots{display:none}
body.touch .announce{top:16%;font-size:clamp(20px,6vw,34px)}
body.touch .slot{width:52px}
body.touch .target-tag{top:calc(46% - 40px)}
body.touch .respawn-overlay,body.touch .scoreboard{z-index:40}

/* mobile / small */
@media (max-width:1000px){
  .menu-main{grid-template-columns:1fr;align-items:center}
  .menu-card{display:none}
  .hero{max-width:640px}
  .hero h1{font-size:clamp(64px,15vw,120px)}
  .menu-meta span:not(.sig){display:none}
  .menu-foot{flex-direction:column;gap:10px;align-items:flex-start}
  .control-ribbon{display:none}
  .radar-wrap{display:none}
  .score-strip{display:none}
  .center-bottom{width:min(340px,46vw)}
  .weapon-slot span{display:none}
}
@media (max-width:700px){
  .menu-main{padding-bottom:28px}

  .menu-main{padding-bottom:28px}
  .hero-copy{max-width:92vw;font-size:14px}
  .menu-actions{flex-wrap:wrap;margin:22px 0}
  .btn-primary{min-width:200px;padding:15px 20px;font-size:13px}
  .quick-stats{display:none}
  .menu-foot .menu-settings{width:100%;justify-content:space-between}
  .menu-top{padding-top:18px}
  .brandmark{font-size:12px}
  .menu-meta{font-size:8px}
  .objective{top:70px;width:150px}
  .killfeed{top:70px;max-width:240px}
  .vitals{transform:scale(.86);transform-origin:bottom left;left:14px;bottom:20px}
  .weapon-panel{transform:scale(.86);transform-origin:bottom right;right:14px;bottom:20px}
  .center-bottom{bottom:20px;width:34vw}
  .weapon-name span{display:none}
  .aim-hint{display:none}
}
@media (max-height:520px) and (pointer:coarse){
  .menu-main{padding-top:4px}
  .hero h1{font-size:clamp(46px,11vh,80px);margin-top:6px}
  .hero-copy{display:none}
  .hero-sub{font-size:11px;margin-bottom:8px}
  .menu-actions{margin:12px 0}
  .quick-stats{display:none}
  .menu-foot{padding-top:8px;padding-bottom:8px}
  .menu-card{display:none}
  body.touch .vitals{transform:scale(.68)}
  body.touch .weapon-panel{transform:scale(.68)}
  body.touch .center-bottom{bottom:calc(126px + var(--safe-b));width:220px}
  body.touch .fuel-wrap{display:none}
  .stick-zone{width:112px;height:112px}
  .t-fire{width:76px;height:76px}
  .t-jump{width:58px;height:58px;margin-bottom:26px}
  .t-weapon{width:48px;height:48px;margin-bottom:64px}
  .t-pause{top:calc(8px + env(safe-area-inset-top,0px))}
}
@media (max-width:600px) and (orientation:portrait){
  .hero h1{font-size:clamp(58px,18vw,96px)}
  .menu-main{padding-left:7vw}
  .hero-copy{max-width:86vw}
  body.touch .vitals{transform:scale(.72)}
  body.touch .weapon-panel{transform:scale(.72)}
  body.touch .center-bottom{width:52vw;bottom:calc(190px + var(--safe-b))}
  .announce{top:20%}
}

/* ---------------- Toast / Boot ---------------- */
.toast{position:absolute;left:50%;bottom:100px;transform:translateX(-50%);z-index:50;font-family:var(--display);font-size:9px;letter-spacing:.16em;color:#dff9ff;background:rgba(8,14,28,.92);border:1px solid rgba(63,233,255,.3);padding:9px 16px;pointer-events:none}
#boot{position:absolute;inset:0;z-index:80;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:16px;background:#05020b;transition:opacity .5s}
#boot.done{opacity:0;pointer-events:none}
.boot-logo{font-family:var(--display);font-size:34px;font-weight:900;font-style:italic;letter-spacing:-.02em;color:#f4fcff}
.boot-logo span{color:var(--cyan);font-size:.7em;margin-left:4px}
.boot-bar{width:220px;height:2px;background:rgba(63,233,255,.15);overflow:hidden}
.boot-bar i{display:block;height:100%;width:0;background:var(--cyan);box-shadow:0 0 12px var(--cyan);animation:bootBar 1.4s ease forwards}
.boot-text{font-family:var(--display);font-size:7.5px;letter-spacing:.26em;color:#5f7c93}

/* ---------------- Animations ---------------- */
@keyframes pulse{0%,100%{opacity:1}50%{opacity:.35}}
@keyframes ping{0%{transform:scale(.6);opacity:.6}100%{transform:scale(1.8);opacity:0}}
@keyframes scan{0%{top:-30%}100%{top:100%}}
@keyframes bootBar{0%{width:0}60%{width:72%}100%{width:100%}}
@keyframes announceIn{0%{opacity:0;transform:translateX(-50%) skewX(-5deg) scale(1.12)}10%{opacity:1;transform:translateX(-50%) skewX(-5deg) scale(1)}80%{opacity:1}100%{opacity:0;transform:translateX(-50%) skewX(-5deg) scale(1.03)}}
@keyframes kfIn{from{opacity:0;transform:translateX(18px)}to{opacity:1;transform:translateX(0)}}
@keyframes hitIn{0%{opacity:1;transform:scale(.55) rotate(8deg)}55%{opacity:1;transform:scale(1.05)}100%{opacity:0;transform:scale(1.25)}}
@keyframes dmgFade{0%{opacity:1;transform:rotate(var(--r)) translateY(-30px) scaleY(1.2)}100%{opacity:0;transform:rotate(var(--r)) translateY(-60px) scaleY(.6)}}
@keyframes quadPulse{0%,100%{opacity:.85}50%{opacity:1}}
@keyframes lowPulse{0%,100%{opacity:1}50%{opacity:.45}}
@keyframes fadeUp{from{opacity:0;transform:translateY(12px)}to{opacity:1;transform:translateY(0)}}

/* subtle glitch on title */
.hero h1::after{content:"";position:absolute;inset:0;background:linear-gradient(90deg,transparent 48%,rgba(63,233,255,.22) 49%,transparent 51%);mix-blend-mode:screen;opacity:0;animation:glitch 7s infinite}
@keyframes glitch{0%,92%,100%{opacity:0;transform:translateX(0)}93%{opacity:1;transform:translateX(-3px)}94%{opacity:.4;transform:translateX(4px)}95%{opacity:1;transform:translateX(0)}}

